; ============================================================
; NTC BASIC keyword library ROM - cpcfw (generated by ntcRomAsm, ntc_compiler.js)
; A background ROM: standard header, no BASIC commands (yet). Programs built with
; Library: ROM find it at their start and call ntc_rom_patch with their jump block.
; ============================================================
			DEVICE AMSTRADCPC6128
NTC_ROMDATA	equ #8800		; its initialised variables (and RAM code), copied by ntc_rom_patch
NTC_ROMBSS	equ #9400		; its other variables, cleared
NTC_STRMAX	equ 255			; strings up to 255 characters (programs built for the ROM use 255)
NTC_MEMBANKS	equ 64			; the Memory class: up to 4MB
NTC_ROM_N	equ 329			; numbers in the index
MEM_WIN		equ #4000
MEM_BADPAGE	equ -2
MEM_BANKS	equ NTC_MEMBANKS	; 0 - 64
MEM_LISTS	equ 6
OVL_NOPAGE	equ -12
OVL_STALE	equ -14			; a page file from another build of the program (its stamp differs)
LST_FIRST	equ 0
LST_LAST	equ 4
LST_COUNT	equ 8
LST_SIZE	equ 10
LST_FREE	equ 12
LST_POOLS	equ 16
LST_HDR		equ 20
LST_NEXT	equ 0
LST_PREV	equ 4
LST_DATA	equ 8
LST_HEADS	equ ntc_buf
LST_TAILS	equ ntc_buf + 1024
NTC_FWBLK	equ #A5F0		; the fast ticker's event block (central 32K, below the firmware)
FS_NOTFOUND	equ -2
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_BADNAME	equ -4
fs_buf			equ ntc_buf		; the 2K buffer CAS IN OPEN / CAS OUT OPEN want (shared with Memory.Copy)
			OUTPUT "NTCFW.ROM"
			ORG #C000 - 128		; an AMSDOS header (WinAPE and ROM tools take it): binary, #C000, 16K
			db 0, "NTCFW   ", "ROM"	; user 0, the file name
			ds 6
			db 2
			dw 0, #C000
			db 0
			dw #4000, #C000
			ds 36
			dw #4000
			db 0
			dw #04D2			; checksum of bytes 0-66
			ds 59
			ORG #C000
ntc_rom_start:
			db 1				; a background ROM
			db 1, 0, 0			; mark, version, modification
			dw ntc_rom_names
			jp ntc_rom_init		; (and one jp per BASIC command, later)
ntc_rom_names:
			db "NTC CPCF", "W" + #80	; the ROM's name (one per platform: they can all be fitted)
			db 0				; (no BASIC commands yet)
ntc_rom_block:				; NTC's part: the program's start code reads it
			db "NTC", 1			; mark, format of this block
			db "CPCFW", 0		; the platform it is for
			dw ntc_rom_patch		; HL = jump block, BC = entries, A = this ROM's number
			dw ntc_rom_index, NTC_ROM_N
; the firmware starts background ROMs at power on: nothing to do (no RAM claimed)
ntc_rom_init:
			scf
			ret
; ntc_rom_patch - (call, from the program, this ROM selected) HL = the program's jump
; block (3 bytes each: jp <number>), BC = its entries, A = this ROM's number. Sets up
; the ROM's RAM (initialised variables copied, the rest cleared), then each number becomes
; the ROM's address. NC = done. C = a number this ROM hasn't got: DE = it.
ntc_rom_patch:
			push hl
			push bc
			push af
			ld hl, ntc_rom_img
			ld de, NTC_ROMDATA
			ld bc, ntc_rom_imgend - ntc_rom_img
			ldir
			ld hl, NTC_ROMBSS
			ld de, NTC_ROMBSS + 1
			ld bc, ntc_rom_bssend - NTC_ROMBSS - 1
			ld (hl), 0
			ldir
			pop af
			ld (ntc_v_rom), a
			pop bc
			pop hl
ntc_rp_lp:
			ld a, b
			or c
			ret z				; all done (NC)
			inc hl				; past the jp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = the number, HL at its high byte
			push hl
			push bc
			ld hl, NTC_ROM_N - 1
			or a
			sbc hl, de
			jr c, ntc_rp_bad		; beyond this ROM's numbers
			ld hl, ntc_rom_index
			add hl, de
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its address
			ld a, d
			or e
			jr z, ntc_rp_bad		; 0: no longer in this ROM
			pop bc
			pop hl
			ld (hl), d
			dec hl
			ld (hl), e
			inc hl
			inc hl				; the next entry
			dec bc
			jr ntc_rp_lp
ntc_rp_bad:
			pop bc
			pop hl
			ld d, (hl)			; DE = the number it hasn't got
			dec hl
			ld e, (hl)
			scf
			ret
; the index: number -> address (0: no longer in this ROM)
ntc_rom_index:
			dw ntc_next		; 0
			dw kw_stop		; 1
			dw ntc_xn		; 2
			dw kw_hookon		; 3
