; ---- the library (code)
;## ntc_data @shared
ntc_next:		ret				; IX target that continues the thread
;## ntc_gstack
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret
;## ntc_xnh ntc_data ntc_islots @shared
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			push af
			ld a, (ntc_hookpend)
			or a
			jr nz, ntc_xn_hookp
			ld a, (ntc_isldue)
			or a
			jr nz, ntc_xn_isl
ntc_xn_none:
			pop af
			ld sp, (ntc_ip)
			ret
ntc_xn_isl:
			ld hl, ntc_isl + 4		; the first slot due and not running
			ld a, (ntc_isln)
			ld b, a
			ld c, 0					; due but still running: stays due
ntc_xi_lp:
			ld a, (hl)
			or a
			jr nz, ntc_xi_skip
			inc hl
			ld a, (hl)
			dec hl
			or a
			jr nz, ntc_xi_run
ntc_xi_skip:
			inc hl
			ld a, (hl)
			dec hl
			or c
			ld c, a
			ld de, 8
			add hl, de
			djnz ntc_xi_lp
			ld a, c
			ld (ntc_isldue), a
			jr ntc_xn_none
ntc_xi_run:
			ld (hl), 1				; running (its return stub clears it)
			inc hl
			ld (hl), 0				; not due
			inc hl
			ld e, (hl)				; Tick's call stub
			inc hl
			ld d, (hl)
			pop af
			ld sp, (ntc_ip)
			ex de, hl
			jp (hl)
ntc_xn_hookp:
			pop af
ntc_xn_hook:
			xor a
			ld (ntc_hookpend), a
			ld (ntc_hookon), a	; not again until the hook returns
			ld sp, (ntc_ip)
			ld hl, (ntc_hook)
			jp (hl)
;## kw_hookon ntc_data @shared
kw_hookon:
			pop hl
			ld (ntc_hook), hl
			ld a, 1
			ld (ntc_hookset), a
			ld (ntc_hookon), a
			ret
;## kw_hookoff ntc_data @shared
kw_hookoff:
			xor a
			ld (ntc_hookset), a
			ld (ntc_hookon), a
			ld (ntc_hookpend), a
			ret
;## kw_turbo_on ntc_data @shared
kw_turbo_on:
			xor a
			ld (ntc_nmode), a
			ret
;## kw_irq ntc_xn @shared
kw_irq:
			jp ntc_xn
;## kw_turbo_off ntc_xn ntc_data @shared
kw_turbo_off:
			ld a, 1
			ld (ntc_nmode), a
			jp ntc_xn
;## kw_goto
kw_goto:
			pop hl
			ld sp, hl
			ret
;## kw_goto (normal mode copy)
kw_goto_n:
			pop hl
			ld sp, hl
			jp ntc_xn
;## kw_goto_iffalse
kw_goto_iffalse:
			pop hl
			ret z
			ld sp, hl
			ret
;## kw_goto_iffalse (normal mode copy)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn
;## kw_goto_iftrue
kw_goto_iftrue:
			pop hl
			ret nz
			ld sp, hl
			ret
;## kw_goto_iftrue (normal mode copy)
kw_goto_iftrue_n:
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn
;## kw_goto_ifzero
kw_goto_ifzero:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			ret nz
			ld sp, hl
			ret
;## kw_goto_ifzero (normal mode copy)
kw_goto_ifzero_n:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn
;## kw_goto_ifnzero
kw_goto_ifnzero:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			ret z
			ld sp, hl
			ret
;## kw_goto_ifnzero (normal mode copy)
kw_goto_ifnzero_n:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn
;## kw_gosub ntc_gstack
kw_gosub:
			pop bc
			ld hl, 0
			add hl, sp
			ex de, hl
			ld hl, (ntc_gsp)
			dec hl
			ld (hl), d
			dec hl
			ld (hl), e
			ld (ntc_gsp), hl
			ld h, b
			ld l, c
			ld sp, hl
			ret
