; ---- code that runs from RAM (addresses may change between ROMs: programs reach it through their jump block)
;## ntc_gfx ntc_data ntc_plat_data @shared  (ROM: runs from RAM)
gfx_begin:
			call ntc_urom_off	; (ROM: the upper ROM hides the screen)
			ld a, (gfx_base)
			cp #40
			ret nz
			push bc
			ld bc, #7FC0
			out (c), c
			pop bc
			ret
gfx_end:
			call ntc_urom_on	; (ROM: the upper ROM hides the screen)
			ld a, (gfx_base)
			cp #40
			ret nz
			ld bc, (ntc_rampt)
			out (c), c
			ret
gfx_width:
			ld a, (ntc_smode)
			ld hl, 160
			or a
			ret z
			add hl, hl
			dec a
			ret z
			add hl, hl
			ret
gfx_line:				; (ROM: the upper ROM off around it)
			call ntc_urom_off
			call gfx_line_r
			jp ntc_urom_on
gfx_line_r:
			ld a, (gfx_clip)
			or a
			jr z, gfx_l_go
			call gfx_width
			ex de, hl
			ld hl, (gfx_x0)
			call gfx_chk
			ret c
			ld hl, (gfx_x1)
			call gfx_chk
			ret c
			ld de, 200
			ld hl, (gfx_y0)
			call gfx_chk
			ret c
			ld hl, (gfx_y1)
			call gfx_chk
			ret c
gfx_l_go:
			ld hl, (gfx_x1)			; left to right
			ld de, (gfx_x0)
			or a
			sbc hl, de
			jr nc, gfx_l_lr
			ld hl, (gfx_x0)
			ld de, (gfx_x1)
			ld (gfx_x0), de
			ld (gfx_x1), hl
			ld hl, (gfx_y0)
			ld de, (gfx_y1)
			ld (gfx_y0), de
			ld (gfx_y1), hl
			ld hl, (gfx_x1)
			ld de, (gfx_x0)
			or a
			sbc hl, de
gfx_l_lr:
			ld (gfx_dx), hl
			ld hl, (gfx_y1)
			ld de, (gfx_y0)
			or a
			sbc hl, de
			ld a, 0
			jr nc, gfx_l_dy
			call gfx_neg
			ld a, 1
gfx_l_dy:
			ld (gfx_sy), a
			ld (gfx_dy), hl
			call gfx_pat			; IYL = the pen's pattern in this mode
			ld a, (gfx_y0)			; HL = the address of (x0, y0)
			ld c, a
			and #F8
			ld l, a
			ld h, 0
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; (y / 8) * 80
			ld a, c
			and 7
			add a, a
			add a, a
			add a, a
			ld c, a
			ld a, (gfx_base)
			add a, c
			add a, h
			ld h, a
			ld de, (gfx_x0)			; + x / pixels a byte, C = the marker
			ld a, (ntc_smode)
			or a
			jr nz, gfx_l_m12
			ld c, #AA
			srl d
			rr e
			jr nc, gfx_l_adr
			ld c, #55
			jr gfx_l_adr
gfx_l_m12:
			dec a
			ld a, e
			jr nz, gfx_l_m2
			and 3
			ld b, a
			ld c, #88
			srl d
			rr e
			srl d
			rr e
			jr gfx_l_sh
gfx_l_m2:
			and 7
			ld b, a
			ld c, #80
			srl d
			rr e
			srl d
			rr e
			srl d
			rr e
gfx_l_sh:
			ld a, b
			or a
			jr z, gfx_l_adr
gfx_l_shl:
			rrc c
			djnz gfx_l_shl
gfx_l_adr:
			add hl, de
			call gfx_begin
			call gfx_l_draw
			jp gfx_end
gfx_l_draw:
			ld a, c					; the first pixel
			and iyl
			xor (hl)
			ld (hl), a
			push hl
			ld hl, (gfx_dx)
			ld de, (gfx_dy)
			or a
			sbc hl, de
			pop hl
			jp c, gfx_ymaj
			ld de, (gfx_dy)			; x major: count dx, error dx / 2, IX = dy
			push de
			pop ix
			ld de, (gfx_dx)
			call gfx_cnt
			ret z
			ld de, (gfx_dx)
			srl d
			rr e
			ld a, (gfx_sy)
			or a
			jp nz, gfx_xu
gfx_xd:
			rrc c					; x + 1
			jr nc, gfx_xd1
			inc hl
gfx_xd1:
			ld a, e					; error - dy
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_xd2
			push hl					; error + dx, y + 1
			ld hl, (gfx_dx)
			add hl, de
			ex de, hl
			pop hl
			ld a, h
			add a, 8
			ld h, a
			and #38
			jr nz, gfx_xd2
			push de
			ld de, #C050
			add hl, de
			pop de
gfx_xd2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_xd
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_xd
			ret
gfx_xu:
			rrc c
			jr nc, gfx_xu1
			inc hl
gfx_xu1:
			ld a, e
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_xu2
			push hl					; error + dx, y - 1
			ld hl, (gfx_dx)
			add hl, de
			ex de, hl
			pop hl
			ld a, h
			sub 8
			ld h, a
			and #38
			cp #38
			jr nz, gfx_xu2
			push de
			ld de, #3FB0
			add hl, de
			pop de
gfx_xu2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_xu
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_xu
			ret
gfx_ymaj:
			ld de, (gfx_dx)			; y major: count dy, error dy / 2, IX = dx
			push de
			pop ix
			ld de, (gfx_dy)
			call gfx_cnt
			ret z
			ld de, (gfx_dy)
			srl d
			rr e
			ld a, (gfx_sy)
			or a
			jp nz, gfx_yu
gfx_yd:
			ld a, h					; y + 1
			add a, 8
			ld h, a
			and #38
			jr nz, gfx_yd1
			push de
			ld de, #C050
			add hl, de
			pop de
gfx_yd1:
			ld a, e					; error - dx
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_yd2
			push hl					; error + dy, x + 1
			ld hl, (gfx_dy)
			add hl, de
			ex de, hl
			pop hl
			rrc c
			jr nc, gfx_yd2
			inc hl
gfx_yd2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_yd
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_yd
			ret
gfx_yu:
			ld a, h					; y - 1
			sub 8
			ld h, a
			and #38
			cp #38
			jr nz, gfx_yu1
			push de
			ld de, #3FB0
			add hl, de
			pop de
gfx_yu1:
			ld a, e
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_yu2
			push hl
			ld hl, (gfx_dy)
			add hl, de
			ex de, hl
			pop hl
			rrc c
			jr nc, gfx_yu2
			inc hl
gfx_yu2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_yu
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_yu
			ret
gfx_cnt:
			ld a, d
			or e
			ret z
			ld b, e
			ld a, e
			or a
			jr z, gfx_cn1
			inc d
gfx_cn1:
			ld a, d
			ld (gfx_out), a
			or 1
			ret
gfx_chk:
			bit 7, h
			scf
			ret nz
			or a
			sbc hl, de
			ccf
			ret
gfx_neg:
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
			ret
gfx_pat:
			ld a, (gfx_pen)
			ld b, a
			ld a, (ntc_smode)
			or a
			jr z, gfx_pt0
			dec a
			jr z, gfx_pt1
			ld a, b					; mode 2: pen 1 = every bit
			and 1
			jr z, gfx_ptset
			ld a, #FF
			jr gfx_ptset
gfx_pt1:
			xor a					; mode 1: pen bit 0 in the high nibble, bit 1 low
			bit 0, b
			jr z, gfx_pt1b
			or #F0
gfx_pt1b:
			bit 1, b
			jr z, gfx_ptset
			or #0F
			jr gfx_ptset
gfx_pt0:
			xor a					; mode 0: bit 0 -> 7, 1 -> 3, 2 -> 5, 3 -> 1 (and one
			bit 0, b				; to the right for the second pixel)
			jr z, gfx_p01
			or #C0
gfx_p01:
			bit 1, b
			jr z, gfx_p02
			or #0C
gfx_p02:
			bit 2, b
			jr z, gfx_p03
			or #30
gfx_p03:
			bit 3, b
			jr z, gfx_ptset
			or #03
gfx_ptset:
			ld iyl, a
			ret
gfx_flip:
			ld a, (gfx_dbl)
			or a
			ret z
			ld b, #F5				; wait for the vertical sync to start
gfx_fw1:
			in a, (c)
			rra
			jr c, gfx_fw1
gfx_fw2:
			in a, (c)
			rra
			jr nc, gfx_fw2
			ld a, (gfx_base)		; show it: CRTC R12 #30 (#C000) / #10 (#4000)
			cp #C0
			ld a, #30
			ld e, #40
			jr z, gfx_fl1
			ld a, #10
			ld e, #C0
gfx_fl1:
			ld (gfx_shown), a
			ld bc, #BC0C
			out (c), c
			inc b
			out (c), a
			ld a, e
			ld (gfx_base), a
			ret
gfx_double:				; (ROM: the upper ROM off around it)
			call ntc_urom_off
			call gfx_double_r
			jp ntc_urom_on
gfx_double_r:
			or a
			jr z, gfx_dboff
			ld (gfx_dbl), a
			ld a, #C0				; show #C000 now
			call gfx_dshow
			ld bc, #7FC0
			out (c), c
			ld hl, #C000
			ld de, #4000
			ld bc, #4000
			ldir
			ld bc, (ntc_rampt)
			out (c), c
			ld a, #40
			ld (gfx_base), a
			ret
gfx_dboff:
			ld (gfx_dbl), a
			ld a, #C0
			ld (gfx_base), a
gfx_dshow:
			ld a, #30
			ld (gfx_shown), a
			ld bc, #BC0C
			out (c), c
			inc b
			out (c), a
			ret
gfx_copyrows:				; (ROM: the upper ROM off around it)
			call ntc_urom_off
			call gfx_copyrows_r
			jp ntc_urom_on
gfx_copyrows_r:
			or a
			ret z
			ld e, a
			ld bc, #7FC0
			out (c), c
			ld d, 8					; 8 lines a row
			ld hl, #C000
gfx_cr1:
			push hl
			push de
			ld b, 0
			ld c, e					; rows * 80 bytes
			ld a, 80
			ld h, b
			ld l, b
gfx_cr2:
			add hl, bc
			dec a
			jr nz, gfx_cr2
			ld b, h
			ld c, l
			pop de
			pop hl
			push hl
			push de
			push hl
			ld a, h
			sub #80
			ld d, a
			ld e, l
			pop hl
			ldir
			pop de
			pop hl
			ld a, h
			add a, 8
			ld h, a
			dec d
			jr nz, gfx_cr1
			ld bc, (ntc_rampt)
			out (c), c
			ret
ntc_urom_off:
			push af
			push bc
			push de
			push hl
			call #B903		; KL U ROM DISABLE
			pop hl
			pop de
			pop bc
			pop af
			ret
ntc_urom_on:
			push af
			push bc
			push de
			push hl
			call #B900		; KL U ROM ENABLE
			pop hl
			pop de
			pop bc
			pop af
			ret
ntc_rom_imgend_r:
			ENT
ntc_rom_imgend:
			ASSERT ntc_rom_imgend_r <= NTC_ROMBSS, "the ROM's initialised variables reach #9400"
			ASSERT $ <= #10000, "the ROM is more than 16K"
			ds #10000 - $, 0		; to 16K
			OUTEND
; ---- the other variables: RAM from NTC_ROMBSS, not in the ROM
			ORG NTC_ROMBSS
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
ntc_gstack:		ds 128
ntc_gstack_top:
ntc_font:		ds 95 * 8
ntc_isl:		ds 32
fs_vol:			ds 9			; the volume in use ("" = not known)
fs_vols:		ds 145			; the volumes that worked, "A,C,M" (up to 16 of up to 8 letters)
fs_tmpn:		ds 9			; a volume name, capitals
fs_rsxn:		ds 17			; a command name (last letter + #80), up to 16 letters
ntc_rpbuf:		ds NTC_STRMAX + 1
ntc_fmbuf:		ds 14
ntc_jnbuf:		ds NTC_STRMAX + 1
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_buf:		ds 2048
mem_head:		ds MEM_LISTS * 2	; each list's first page
mem_cnt:		ds MEM_LISTS * 2	; and how many (must follow mem_head)
mem_bank:		ds MEM_BANKS * 2 + 1	; per bank found: setting for its page 0, port high byte
mem_save:		ds MEM_BANKS + 1	; probe: the bytes the markers replace
lst_h:			ds 4			; the list's header
lst_n:			ds 4			; nodes, far pointers (address, page)
lst_m:			ds 4
lst_k:			ds 4
lst_p:			ds 4
lst_q:			ds 4
lst_s1:			ds 4
lst_s2:			ds 4
